css:
.pv{position:relative;--fg:#171717;--fg2:#525252;--fg3:#737373;--fg4:#A3A3A3;--bg:#fff;--bg2:#FAFAFA;--muted:#F5F5F5;--line:#E5E5E5;--line2:#D4D4D4;--solid:#171717;--on:#fff;
 --err:#B42318;--err-bd:#F04438;--err-bg:#FEF3F2;--focus:#171717;--ring:rgba(23,23,23,.14);--sel:#F5F5F5;--scrim:rgba(10,10,10,.45);--shadow:0 12px 16px -4px rgba(10,13,18,.08),0 4px 6px -2px rgba(10,13,18,.03);
 color:var(--fg);font:14px/20px Inter,system-ui,sans-serif}
.pv[data-theme=dark]{--fg:#F5F5F5;--fg2:#D4D4D4;--fg3:#A3A3A3;--fg4:#737373;--bg:#0A0A0A;--bg2:#111;--muted:#171717;--line:#262626;--line2:#404040;--solid:#F5F5F5;--on:#0A0A0A;
 --err:#FFA19C;--err-bd:#F97066;--err-bg:#3A1210;--focus:#F5F5F5;--ring:rgba(245,245,245,.18);--sel:#1F1F1F;--scrim:rgba(0,0,0,.6);--shadow:0 12px 16px -4px rgba(0,0,0,.5)}
.i{flex:none;display:block}
button{font:inherit;color:inherit}
/* ---- field ---- */
.f{display:flex;flex-direction:column;gap:6px;min-width:0;position:relative}
.lb{font:500 14px/20px Inter;color:var(--fg2);display:flex;gap:4px;align-items:center}
.lb .req{color:var(--err)}
.lb .hi{color:var(--fg4);display:inline-flex}
.hn{font-size:12.5px;line-height:18px;color:var(--fg3)}
.fe{font-size:12.5px;line-height:18px;color:var(--err);display:flex;gap:6px;align-items:center}
/* ---- ô control (input, select trigger, multiselect) ---- */
.ctl{--h:32px;display:flex;align-items:center;gap:8px;min-height:var(--h);box-sizing:border-box;border:1px solid var(--line2);border-radius:8px;background:var(--bg);
 padding:0 12px;color:var(--fg);font:400 14px/20px Inter;min-width:0;position:relative;cursor:text}
.ctl.s-sm{--h:28px;font-size:13px;padding:0 10px;gap:6px}.ctl.s-lg{--h:40px;font-size:15px;padding:0 14px}
.ctl .v{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ctl .ph{flex:1;min-width:0;color:var(--fg4);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ctl .ic{color:var(--fg3);display:inline-flex;flex:none}
.ctl .sub{color:var(--fg3);white-space:nowrap}
.ctl.is-hover{border-color:var(--fg3)}
.ctl.is-focus,.ctl.is-open{border-color:var(--focus);box-shadow:inset 0 0 0 1px var(--focus)}
.ctl.is-dis{background:var(--muted);color:var(--fg4);cursor:not-allowed}.ctl.is-dis .ic,.ctl.is-dis .v{color:var(--fg4)}
.ctl.is-err{border-color:var(--err-bd)}.ctl.is-err.is-focus{box-shadow:inset 0 0 0 1px var(--err-bd)}
.ctl.is-ro{background:var(--muted);border-color:var(--line);cursor:default}
.ctl .eic{color:var(--err-bd);display:inline-flex}
/* trạng thái theo Bảng chọn (phần tử data-live) */
.pv[data-state=hover] [data-live]>.ctl{border-color:var(--fg3)}
.pv[data-state=focus] [data-live]>.ctl,.pv[data-state=open] [data-live]>.ctl{border-color:var(--focus);box-shadow:inset 0 0 0 1px var(--focus)}
.pv[data-state=disabled] [data-live]>.ctl{background:var(--muted);color:var(--fg4)}
.pv[data-state=error] [data-live]>.ctl{border-color:var(--err-bd)}
.pv[data-state=readonly] [data-live]>.ctl{background:var(--muted);border-color:var(--line)}
/* addon chữ đầu/cuối, nút cuối */
.ad{align-self:stretch;display:flex;align-items:center;color:var(--fg3);white-space:nowrap;flex:none}
.ad.l{margin-left:-12px;padding:0 10px 0 12px;border-right:1px solid var(--line2);border-radius:7px 0 0 7px}
.ad.r{margin-right:-12px;padding:0 12px 0 10px;border-left:1px solid var(--line2);border-radius:0 7px 7px 0}
.ad.dd{gap:4px;color:var(--fg)}
.ab{align-self:stretch;margin:-1px -13px -1px 0;padding:0 12px;border:1px solid var(--line2);border-radius:0 8px 8px 0;background:var(--bg);display:flex;align-items:center;gap:6px;font:600 13px Inter;color:var(--fg2);white-space:nowrap}
/* ---- tag ---- */
.tg{--th:24px;display:inline-flex;align-items:center;gap:4px;height:var(--th);box-sizing:border-box;padding:0 8px;border:1px solid var(--line2);border-radius:6px;background:var(--bg);color:var(--fg2);font:500 12px/18px Inter;white-space:nowrap;max-width:200px;vertical-align:middle}
.tg.t-sm{--th:22px;padding:0 6px;font-size:12px}.tg.t-lg{--th:28px;padding:0 10px;font-size:13.5px;gap:6px}
.tg .tl{min-width:0;overflow:hidden;text-overflow:ellipsis}
.tg .ct{font-weight:600;font-size:11.5px;line-height:16px;background:var(--muted);color:var(--fg2);border-radius:3px;padding:0 5px;margin-left:2px}
.tg .x{display:inline-flex;color:var(--fg4);border-radius:3px;margin-right:-3px;padding:1px;border:0;background:none;cursor:pointer}
.tg .x:hover{background:var(--muted);color:var(--fg2)}
.tg .av{width:16px!important;height:16px!important;font-size:8px!important}
.tg.is-hover{background:var(--bg2);border-color:var(--fg4)}
.tg.is-focus{box-shadow:0 0 0 2px var(--bg),0 0 0 4px var(--focus)}
.tg.is-dis{opacity:.5}
.dot{width:6px;height:6px;border-radius:50%;flex:none;display:inline-block}
.av{border-radius:50%;display:inline-grid;place-items:center;font-weight:600;flex:none}
.flag{flex:none;display:block;border-radius:2px}
.cbx{width:14px;height:14px;border:1px solid var(--line2);border-radius:4px;display:inline-grid;place-items:center;flex:none;background:var(--bg);box-sizing:border-box}
.cbx.on{background:var(--solid);border-color:var(--solid);color:var(--on)}
.mi .cbx,.ro .cbx{width:16px;height:16px}
/* ---- menu (popover) ---- */
.mn{border:1px solid var(--line);border-radius:8px;background:var(--bg);box-shadow:var(--shadow);padding:4px;display:flex;flex-direction:column;gap:1px;min-width:200px;box-sizing:border-box;max-height:320px;overflow:auto}
.mi{min-height:36px;display:flex;align-items:center;gap:8px;padding:0 8px;border-radius:6px;font:500 14px/20px Inter;color:var(--fg);cursor:pointer;box-sizing:border-box}
.mi .ml{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mi .ms{color:var(--fg3);font-weight:400;margin-left:6px}
.mi .ic{color:var(--fg3);display:inline-flex}
.mi .ck{color:var(--fg);display:inline-flex;margin-left:auto}
.mi.hov,.mi:hover{background:var(--muted)}
.mi.sel{font-weight:600}
.mi.dis{color:var(--fg4);cursor:not-allowed}.mi.dis .ic{color:var(--fg4)}.mi.dis:hover{background:none}
.mi.dang{color:var(--err)}.mi.dang .ic{color:var(--err)}
.mh{padding:8px 8px 4px;font:600 12px/18px Inter;color:var(--fg3)}
.mdv{height:1px;background:var(--line);margin:4px -4px}
.msr{display:flex;align-items:center;gap:8px;height:36px;padding:0 8px;border-bottom:1px solid var(--line);margin:-4px -4px 4px;color:var(--fg4)}
.mem{padding:20px 12px;text-align:center;color:var(--fg3);font-size:13px}
.mem b{display:block;color:var(--fg);font-weight:600;margin-bottom:2px}
.kbd{margin-left:auto;font:500 11px/16px Inter;color:var(--fg3);border:1px solid var(--line);border-radius:4px;padding:0 4px}
.scb{position:absolute;right:3px;top:8px;width:4px;height:60px;border-radius:2px;background:var(--line2)}
/* option nhiều thông tin */
.ro{display:flex;gap:10px;align-items:flex-start;padding:8px;border-radius:6px;cursor:pointer}
.ro.hov,.ro:hover{background:var(--muted)}
.ro .ri{width:32px;height:32px;border-radius:8px;background:var(--muted);display:grid;place-items:center;color:var(--fg2);flex:none}
.ro .rm{flex:1;min-width:0}
.ro .r1{display:flex;gap:6px;align-items:center;font:600 14px/20px Inter;min-width:0}
.ro .r1 .code{font:600 13px/20px "JetBrains Mono",ui-monospace,monospace;white-space:nowrap;flex:none}
.ro .r2{font-size:12.5px;line-height:18px;color:var(--fg3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ro .rr{margin-left:auto;text-align:right;font-size:12.5px;color:var(--fg3);white-space:nowrap}
.ro .ck{color:var(--fg);display:inline-flex;align-self:center}
.chip{display:inline-flex;align-items:center;gap:4px;font:500 11.5px/16px Inter;padding:2px 8px;border-radius:999px;background:var(--muted);color:var(--fg2);white-space:nowrap}
.chip.ok{background:#ECFDF3;color:#067647}.chip.wa{background:#FFFAEB;color:#B54708}.chip.er{background:#FEF3F2;color:#B42318}
.pv[data-theme=dark] .chip.ok{background:#053321;color:#75E0A7}.pv[data-theme=dark] .chip.wa{background:#4E1D09;color:#FEC84B}.pv[data-theme=dark] .chip.er{background:#55160C;color:#FDA29B}
/* ---- mobile ---- */
.m .ctl{--h:48px;border-radius:12px;padding:0 16px;font-size:16px}
.m .lb{font-size:14px}
.sht{position:absolute;left:0;right:0;bottom:0;z-index:9;background:var(--bg);border-radius:24px 24px 0 0;padding:8px 0 24px;display:flex;flex-direction:column;max-height:78%;box-shadow:0 -8px 24px rgba(0,0,0,.12)}
.sht .hd{width:36px;height:4px;border-radius:2px;background:var(--line2);align-self:center;margin-bottom:8px;flex:none}
.sht .sh-t{font:600 17px/24px Inter;padding:4px 16px 8px;display:flex;align-items:center;justify-content:space-between}
.sht .sh-b{overflow:auto;padding:0 8px}
.sht .mi{min-height:52px;font-size:16px;padding:0 12px;border-radius:10px}
.sht .ro{padding:10px 12px}
.sht .sh-f{padding:12px 16px 0;border-top:1px solid var(--line);display:flex;gap:8px}
.sht .msr{margin:0 16px 8px;border:1px solid var(--line2);border-radius:12px;height:44px;padding:0 12px}
.scr{position:absolute;inset:0;background:var(--scrim);z-index:8}
.bt{height:32px;padding:0 12px;border:1px solid var(--line2);border-radius:8px;background:var(--bg);display:inline-flex;align-items:center;justify-content:center;gap:6px;font:600 13.5px/18px Inter;white-space:nowrap;cursor:pointer;color:var(--fg)}
.bt.pri{background:var(--solid);color:var(--on);border-color:var(--solid)}
.bt.big{height:48px;border-radius:12px;font-size:15px;flex:1}
.bt.ic-only{width:32px;padding:0}
.bt.ghost{border-color:transparent;background:none}
/* ---- bảng biến thể (màn Biến thể) ---- */
.vg{padding:20px 24px 32px;display:flex;flex-direction:column;gap:20px;background:var(--bg)}
.vg h3{margin:0;font:600 15px/22px Inter;display:flex;gap:8px;align-items:baseline}
.vg h3 small{font:400 12.5px Inter;color:var(--fg3)}
.vgr{display:grid;gap:14px 18px;align-items:start}
.vgc{display:flex;flex-direction:column;gap:6px;min-width:0}
.vgc>.tg,.vgc>.bt{align-self:flex-start}
.vgc>.cap{font:500 11.5px/16px Inter;color:var(--fg3);letter-spacing:.2px}
.vgs{border-top:1px solid var(--line);padding-top:16px;display:flex;flex-direction:column;gap:12px}
.pv[data-platform=mobile] .vg{padding:12px 16px 96px;gap:16px}

.ctl.sel{cursor:pointer}
.ctl.sel .chev{margin-left:auto;color:var(--fg3)}
.pv[data-state=open] [data-live] .chev{transform:rotate(180deg)}
.pv[data-state=long] [data-live] .nl{display:none}
.pv[data-state=error] [data-live] .nh{display:none}
.pv[data-state=open][data-D5=a] [data-live]>.ctl:has(.tp) .nl,.pv[data-state=empty][data-D5=a] [data-live]>.ctl:has(.tp) .nl{display:none}
.pv[data-state=empty] [data-live]>.ctl{border-color:var(--focus);box-shadow:inset 0 0 0 1px var(--focus)}
.caret{display:inline-block;width:1px;height:16px;background:var(--fg);margin-left:1px;vertical-align:-3px}
.ctl .rv{flex:1;min-width:0}
.rv1,.rv2{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rv1{font-weight:500}.rv2{font-size:12.5px;line-height:16px;color:var(--fg3)}
.pv[data-D3=a] .rv2{display:none}
.pv[data-D3=b] .ctl.rich{padding-top:5px;padding-bottom:5px}
.pv[data-D3=b] .m .ctl.rich{padding-top:8px;padding-bottom:8px}
.ctl.nat{background:var(--bg2)}
.pop{min-width:100%}
.pv[data-D7=a] .pop{width:100%}
.pv[data-D7=b] .pop{width:max-content;max-width:480px}
.pop .mn{width:100%}
/* D1 dấu đã chọn */
.rd{display:none;width:16px;height:16px;border:1px solid var(--line2);border-radius:50%;flex:none;box-sizing:border-box}
.rd.on{border:5px solid var(--solid)}
.pv[data-D1=c] .rd{display:inline-block}.pv[data-D1=c] .mi .ck,.pv[data-D1=c] .ro .ck{display:none}
.pv[data-D1=b] .mi.sel,.pv[data-D1=b] .ro.sel{background:var(--sel)}
.pv[data-D1=c] .ro .rd{align-self:center}
/* D2 option nhiều thông tin */
.ro .rt{font-weight:500;color:var(--fg2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.pv[data-D2=a] .ro .ri,.pv[data-D2=a] .ro .rr,.pv[data-D2=a] .ro .av{display:none}
.pv[data-D2=b] .ro{align-items:center;padding:6px 8px}
.pv[data-D2=b] .ro .ri,.pv[data-D2=b] .ro .av{display:none}
.pv[data-D2=b] .ro .rm{display:flex;align-items:center;gap:12px}
.pv[data-D2=b] .ro .r1{flex:none;max-width:60%}
.pv[data-D2=b] .ro .r2{margin-left:auto;flex:1;text-align:right;min-width:0}
.pv[data-D2=b] .ro .rr{display:none}
.pv[data-D2=c] .ro .rr{align-self:center}
/* D4 chữ phụ */
.mi .ml .ms{font-weight:400}
.pv[data-D4=b] .mi:has(.ms){padding-top:6px;padding-bottom:6px}
.pv[data-D4=b] .mi .ml{white-space:normal}
.pv[data-D4=b] .mi .ms{display:block;margin:0;font-size:12.5px;line-height:16px}
/* app */
.fs{position:absolute;inset:0;background:var(--bg);z-index:9;display:flex;flex-direction:column}
.fs .fs-h{height:52px;display:flex;align-items:center;gap:8px;padding:44px 16px 0;box-sizing:content-box;font:600 17px Inter}
.fs .msr{margin:8px 16px;border:1px solid var(--line2);border-radius:12px;height:44px;padding:0 12px}
.fs .fs-b{flex:1;overflow:auto;padding:0 8px}
.fs .ro{padding:12px}
.whl{display:flex;flex-direction:column;align-items:center;padding:8px 0 16px;font:400 18px/40px Inter;color:var(--fg4)}
.whl .on{color:var(--fg);font-weight:500;background:var(--muted);border-radius:10px;width:calc(100% - 32px);text-align:center}
.mn.vgm{box-shadow:var(--shadow);max-height:none}
.sht.static,.fs.static{position:relative;border-radius:16px;max-height:none;box-shadow:none;border:1px solid var(--line)}
.fs.static .fs-h{padding-top:0}
.pvm:not([data-D1="a"]) [data-mshow~="D1:a"],.pvm:not([data-D1="b"]) [data-mshow~="D1:b"],.pvm:not([data-D1="c"]) [data-mshow~="D1:c"],.pvm:not([data-D2="a"]) [data-mshow~="D2:a"],.pvm:not([data-D2="b"]) [data-mshow~="D2:b"],.pvm:not([data-D2="c"]) [data-mshow~="D2:c"],.pvm:not([data-D3="a"]) [data-mshow~="D3:a"],.pvm:not([data-D3="b"]) [data-mshow~="D3:b"],.pvm:not([data-D4="a"]) [data-mshow~="D4:a"],.pvm:not([data-D4="b"]) [data-mshow~="D4:b"],.pvm:not([data-D5="a"]) [data-mshow~="D5:a"],.pvm:not([data-D5="b"]) [data-mshow~="D5:b"],.pvm:not([data-D6="a"]) [data-mshow~="D6:a"],.pvm:not([data-D6="b"]) [data-mshow~="D6:b"],.pvm:not([data-D6="c"]) [data-mshow~="D6:c"],.pvm:not([data-D7="a"]) [data-mshow~="D7:a"],.pvm:not([data-D7="b"]) [data-mshow~="D7:b"],.pvm [data-mshow*="state:"]{display:none!important}.pv[data-theme=dark] .pv{--fg:#F5F5F5;--fg2:#D4D4D4;--fg3:#A3A3A3;--fg4:#737373;--bg:#0A0A0A;--bg2:#111;--muted:#171717;--line:#262626;--line2:#404040;--solid:#F5F5F5;--on:#0A0A0A;
 --err:#FFA19C;--err-bd:#F97066;--err-bg:#3A1210;--focus:#F5F5F5;--ring:rgba(245,245,245,.18);--sel:#1F1F1F;--scrim:rgba(0,0,0,.6);--shadow:0 12px 16px -4px rgba(0,0,0,.5)}

cssScreen:
.pad{padding:16px 24px 24px;display:flex;flex-direction:column;gap:16px}.mpad{padding:8px 16px 96px;display:flex;flex-direction:column;gap:16px}
table{width:100%;border-collapse:collapse}td,th{padding:10px 16px;border-bottom:1px solid var(--line);text-align:left;font-size:13px;vertical-align:middle}th{color:var(--fg3);font-weight:500;background:var(--muted);white-space:nowrap}
.tb{border:1px solid var(--line);border-radius:12px;overflow:visible}
.tb tr:last-child td{border-bottom:0}
.card{border:1px solid var(--line);border-radius:12px;padding:16px 20px;display:flex;flex-direction:column;gap:16px;background:var(--bg)}
.card .h{font:600 15px/22px Inter;display:flex;justify-content:space-between;align-items:center}
.grid2{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px 20px}
.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px 20px}
.span2{grid-column:span 2}
.form{max-width:760px}
.acts{display:flex;justify-content:flex-end;gap:8px}
.bar{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.mono{font-family:"JetBrains Mono",ui-monospace,monospace;font-size:12.5px}
.mcard{border:1px solid var(--line);border-radius:16px;padding:12px 14px;display:flex;flex-direction:column;gap:6px;background:var(--bg)}
.mcard b{font-size:15px}.mcard .s{color:var(--fg3);font-size:13px}
.mfoot{position:absolute;left:0;right:0;bottom:0;padding:12px 16px 28px;background:var(--bg);border-top:1px solid var(--line);display:flex;gap:8px;z-index:5}
.anchor{position:relative}
.pop{position:absolute;z-index:20;top:calc(100% + 4px);left:0}
.pop.r{left:auto;right:0}
.pv[data-platform=mobile] .grid2,.pv[data-platform=mobile] .grid3{grid-template-columns:1fr}
.pv[data-platform=mobile] .span2{grid-column:auto}
